    text-align: center;
}

.profile-avatar {
    width: 140px;
    height: 140px;
    border-radius: 50%;
    border: 5px solid #00ffff;
    box-shadow: 0 0 15px #00ffff, 0 0 30px rgba(0, 255, 255, 0.5);
    object-fit: cover;
    margin-bottom: 15px;
    animation: pulse 2s infinite alternate;
}

@keyframes pulse {
    from { box-shadow: 0 0 10px #00ffff, 0 0 20px rgba(0, 255, 255, 0.4); }
    to { box-shadow: 0 0 20px #00ffff, 0 0 40px rgba(0, 255, 255, 0.6); }
}

.profile-name {
    font-size: 2.8em;
    font-weight: 700;
    color: #00ffff;
    text-shadow: 0 0 10px rgba(0, 255, 255, 0.5);
    letter-spacing: 2px;
}

.profile-bio {
    font-size: 1.1em;
    line-height: 1.7;
    color: #c0c0c0;
    margin-bottom: 35px;
    text-align: center;
    max-width: 650px;
    margin-left: auto;
    margin-right: auto;
}

.profile-stats {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
    gap: 25px;
    margin-top: 30px;
    padding: 25px;
    background: #0f0f20;
    border-radius: 8px;
    border: 1px solid rgba(0, 255, 255, 0.1);
}

.profile-stat {
    text-align: center;
    padding: 20px;
    background: #1e1e30;
    border-radius: 5px;
    border-left: 3px solid #00ffff;
    transition: background 0.3s ease, transform 0.2s ease;
}

.profile-stat:hover {
    background: #2a2a40;
    transform: translateY(-3px);
    box-shadow: 0 0 10px rgba(0, 255, 255, 0.3);
}

.profile-stat strong {
    display: block;
    font-size: 2.5em;
    color: #39ff14;
    margin-bottom: 8px;
    text-shadow: 0 0 8px rgba(57, 255, 20, 0.7);
}

.profile-stat span {
    font-size: 0.95em;
    color: #a0a0a0; /* Changed from #888 to improve visibility */
